<script lang="ts">
import {browser} from '$app/environment';import {page} from '$app/state';import {goto} from '$app/navigation';import {fellows,zones} from '$lib/data/fellows';import FellowCard from '$lib/components/FellowCard.svelte';
let query=$state('');let cohort=$state('all');let zone=$derived(browser ? page.url.searchParams.get('zone')||'all' : 'all');let sort=$state('directory');
let filtered=$derived(fellows.filter(f=> (zone==='all'||f.zones.some(z=>z===zone))&&(cohort==='all'||String(f.cohort)===cohort)&&(!query||[f.name,...f.zones.map(z=>zones.find(x=>x.id===z)?.name)].join(' ').toLowerCase().includes(query.toLowerCase()))).toSorted((a,b)=>sort==='name'?a.name.localeCompare(b.name):0));
function setZone(value:string){const params=new URLSearchParams(page.url.searchParams);if(value==='all')params.delete('zone');else params.set('zone',value);goto('/fellows'+(params.size?'?'+params:''),{noScroll:true,keepFocus:true});}
function reset(){query='';cohort='all';sort='directory';setZone('all');}
</script>
<svelte:head><title>Discover our fellows — beVisioneers Harare Hub</title><meta name="description" content="Explore 45 beVisioneers Harare fellows by name, cohort and climate impact zone."/></svelte:head>
<section class="page-hero purple"><p class="eyebrow">OUR COMMUNITY / HARARE</p><h1>Meet the minds.<br/>Find your connection.<span class="heading-star" aria-hidden="true">✳</span></h1><p>Different backgrounds. Shared ambition. Discover the young people<br class="desktop-break"/> working towards a planet-positive future.</p><div class="hero-footnote">45 FELLOWS <span>·</span> 9 IMPACT ZONES <span>·</span> ONE SHARED PLANET</div></section>
<section class="section directory"><div class="filters"><label class="search-label">Search the community<input type="search" bind:value={query} placeholder="Search by name or impact area…"/></label><label>Climate impact zone<select value={zone} onchange={e=>setZone(e.currentTarget.value)}><option value="all">All impact zones</option>{#each zones as z}<option value={z.id}>{z.name}</option>{/each}</select></label><label>Cohort<select bind:value={cohort}><option value="all">All cohorts</option><option value="3">Cohort 3</option><option value="4">Cohort 4</option></select></label></div><div class="results-bar"><p aria-live="polite"><strong>{filtered.length}</strong> {filtered.length===1?'fellow':'fellows'} to discover</p><label class="sort-label">Sort by<select bind:value={sort}><option value="directory">Directory order</option><option value="name">Name A–Z</option></select></label></div>{#if filtered.length}<div class="fellows-grid directory-grid">{#each filtered as fellow (fellow.slug)}<FellowCard {fellow} index={fellows.indexOf(fellow)}/>{/each}</div>{:else}<div class="empty-state"><span aria-hidden="true">✳</span><h2>No fellows found just yet.</h2><p>Try another name or broaden your filters.</p><button class="button dark" onclick={reset}>Clear all filters <span>↻</span></button></div>{/if}</section>
